sys_script_include.script:
var DateDowOrderUtils = Class.create();
DateDowOrderUtils.prototype = {
    initialize: function() {},

    /**
     * Returns weekday value and order
     * @param {GlideDate} glideDate
     * @returns {Object}
     */
    getDayAndOrder: function(glideDate) {

        if (!glideDate)
            return null;

        // 1 = Monday, 6 = Saturday
        var dayNumber = glideDate.getDayOfWeekLocalTime();

        var dayMap = {
            1: {
                value: 'monday',
                label: 'Monday',
                baseOrder: 100
            },
            2: {
                value: 'tuesday',
                label: 'Tuesday',
                baseOrder: 200
            },
            3: {
                value: 'wednesday',
                label: 'Wednesday',
                baseOrder: 300
            },
            4: {
                value: 'thursday',
                label: 'Thursday',
                baseOrder: 400
            },
            5: {
                value: 'friday',
                label: 'Friday',
                baseOrder: 500
            },
            6: {
                value: 'saturday',
                label: 'Saturday',
                baseOrder: 600

            }
        };

        return dayMap[dayNumber] || null;
    },

    type: 'DateDowOrderUtils'
};
